import random
from typing import List

# Generator for Linux console font (PSF1-like) raw bitmap of 256 glyphs, 8x16 each -> 4096 bytes.
# rfbLoadConsoleFont expects a file containing 256 glyphs of 8x16 monochrome bitmaps laid out
# consecutively, one glyph after another, 16 bytes per glyph, 1 byte per row, MSB-first bits.
# No header or Unicode table is included.

WIDTH = 8
HEIGHT = 16
GLYPHS = 256
BYTES_PER_GLYPH = HEIGHT  # 1 byte per row
TOTAL_SIZE = GLYPHS * BYTES_PER_GLYPH  # 4096

# Helpers to build simple useful glyph patterns

def glyph_blank() -> List[int]:
    return [0x00] * HEIGHT


def glyph_full() -> List[int]:
    return [0xFF] * HEIGHT


def glyph_box() -> List[int]:
    # 8x16 box outline
    rows = [0] * HEIGHT
    rows[0] = 0xFF
    rows[-1] = 0xFF
    for y in range(1, HEIGHT - 1):
        rows[y] = 0x81  # 1000 0001
    return rows


def glyph_checker(step_y: int = 1) -> List[int]:
    # Alternating rows 0xAA/0x55 pattern
    rows = []
    for y in range(HEIGHT):
        if ((y // step_y) % 2) == 0:
            rows.append(0xAA)  # 10101010
        else:
            rows.append(0x55)  # 01010101
    return rows


def glyph_diagonal(main: bool = True) -> List[int]:
    # Draw a diagonal line using MSB-first bits
    rows = [0] * HEIGHT
    for y in range(HEIGHT):
        if main:
            x = min(WIDTH - 1, y * WIDTH // HEIGHT)  # from left-top to right-bottom
        else:
            x = WIDTH - 1 - (min(WIDTH - 1, y * WIDTH // HEIGHT))  # other diagonal
        rows[y] = 1 << (7 - x)
    return rows


def glyph_vert_bar(x: int) -> List[int]:
    x = max(0, min(WIDTH - 1, x))
    mask = 1 << (7 - x)
    return [mask] * HEIGHT


def glyph_horiz_bar(y1: int, y2: int) -> List[int]:
    y1 = max(0, min(HEIGHT - 1, y1))
    y2 = max(0, min(HEIGHT - 1, y2))
    if y1 > y2:
        y1, y2 = y2, y1
    rows = [0] * HEIGHT
    for y in range(y1, y2 + 1):
        rows[y] = 0xFF
    return rows


def glyph_digit(n: int) -> List[int]:
    # Simple 5x7 digits mapped into 8x16 area (top-left aligned, doubled vertically)
    # 5x7 font patterns (MSB-first in 5 bits):
    digits = {
        0: [0b11111, 0b10001, 0b10011, 0b10101, 0b11001, 0b10001, 0b11111],
        1: [0b00100, 0b01100, 0b00100, 0b00100, 0b00100, 0b00100, 0b01110],
        2: [0b11110, 0b00001, 0b00001, 0b11110, 0b10000, 0b10000, 0b11111],
        3: [0b11110, 0b00001, 0b00001, 0b01110, 0b00001, 0b00001, 0b11110],
        4: [0b10010, 0b10010, 0b10010, 0b11111, 0b00010, 0b00010, 0b00010],
        5: [0b11111, 0b10000, 0b10000, 0b11110, 0b00001, 0b00001, 0b11110],
        6: [0b11111, 0b10000, 0b10000, 0b11111, 0b10001, 0b10001, 0b11111],
        7: [0b11111, 0b00001, 0b00010, 0b00100, 0b01000, 0b10000, 0b10000],
        8: [0b11111, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b11111],
        9: [0b11111, 0b10001, 0b10001, 0b11111, 0b00001, 0b00001, 0b11111],
    }
    pat = digits.get(n % 10, digits[0])
    rows = [0] * HEIGHT
    for i, row5 in enumerate(pat):
        # place in top area and double vertically to be taller
        byte = (row5 << 3) & 0xF8  # align to MSB within 8 bits
        y = i * 2
        if y < HEIGHT:
            rows[y] = byte
        if y + 1 < HEIGHT:
            rows[y + 1] = byte
    return rows


def pack_glyphs(glyphs: List[List[int]]) -> bytes:
    out = bytearray()
    for g in glyphs:
        if len(g) != HEIGHT:
            # pad or trim to HEIGHT
            g = (g + [0] * HEIGHT)[:HEIGHT]
        for b in g:
            out.append(b & 0xFF)
    return bytes(out[:TOTAL_SIZE])


def build_font(seed: int) -> bytes:
    rnd = random.Random(seed)

    glyphs: List[List[int]] = []

    # Reserve first ASCII region with readable/basic shapes for stability
    # 0..31 control -> blanks or simple bars
    for i in range(32):
        if i in (9, 10, 13):
            glyphs.append(glyph_horiz_bar(7, 8))
        else:
            glyphs.append(glyph_blank())

    # ASCII 32 space
    glyphs.append(glyph_blank())

    # Printable ASCII 33..126: mix of patterns and occasional digits/lines
    for code in range(33, 127):
        choice = rnd.randint(0, 6)
        if choice == 0:
            g = glyph_box()
        elif choice == 1:
            g = glyph_checker(step_y=rnd.choice([1, 2, 4]))
        elif choice == 2:
            g = glyph_diagonal(main=True)
        elif choice == 3:
            g = glyph_diagonal(main=False)
        elif choice == 4:
            g = glyph_vert_bar(rnd.randrange(0, WIDTH))
        elif choice == 5:
            y1 = rnd.randrange(0, HEIGHT)
            y2 = rnd.randrange(0, HEIGHT)
            g = glyph_horiz_bar(y1, y2)
        else:
            g = glyph_digit((code - 48) % 10)
        glyphs.append(g)

    # DEL 127 -> blank
    glyphs.append(glyph_blank())

    # The rest 128..255: random but valid patterns focusing on different variability
    for code in range(128, GLYPHS):
        mode = rnd.randint(0, 7)
        if mode == 0:
            g = glyph_full()
        elif mode == 1:
            g = [rnd.getrandbits(8) for _ in range(HEIGHT)]
        elif mode == 2:
            # top half filled
            g = [0xFF if y < HEIGHT // 2 else 0x00 for y in range(HEIGHT)]
        elif mode == 3:
            # left half filled (set MSB 4 bits)
            g = [0xF0 for _ in range(HEIGHT)]
        elif mode == 4:
            # right half filled (LSB 4 bits)
            g = [0x0F for _ in range(HEIGHT)]
        elif mode == 5:
            g = glyph_checker(step_y=2)
        elif mode == 6:
            g = glyph_vert_bar(rnd.randrange(0, WIDTH))
        else:
            g = glyph_horiz_bar(rnd.randrange(0, HEIGHT), rnd.randrange(0, HEIGHT))
        glyphs.append(g)

    # Ensure we have exactly 256 glyphs
    if len(glyphs) < GLYPHS:
        glyphs.extend([glyph_blank() for _ in range(GLYPHS - len(glyphs))])
    elif len(glyphs) > GLYPHS:
        glyphs = glyphs[:GLYPHS]

    data = pack_glyphs(glyphs)
    # Safety: enforce exact size
    if len(data) != TOTAL_SIZE:
        data = data[:TOTAL_SIZE].ljust(TOTAL_SIZE, b"\x00")
    return data


def generate(seed: int) -> bytes:
    return build_font(seed)
